import React, { useEffect, useRef, useState } from 'react';
import type { INode } from 'svgson';

import type { FileSource } from './../ricos-schema/next-schema/index.js';
import { resolveDocumentColorToCss } from './/theme-color-token.js';
import { DoubleLoader } from './../ui-components/Components/double-loader.js';

import { ALLOWED_SHAPE_ATTRIBUTES, DEFAULT_COLOR } from './shape-view-renderer/consts.js';
import { getParsedShape } from './shape-view-renderer/get-parsed-shape.js';
import styles from './shape-view-renderer/shape-view-renderer-scss.js';

// SVG paint values that mean "draw nothing" — preserve them as-is so a stroke-only
// shape doesn't get filled, and a fill-only shape doesn't get an outline.
const isEmptyPaint = (value: string | undefined): boolean =>
  value === 'none' || value === 'transparent';

const hasAnyStroke = (node: INode | undefined): boolean => {
  if (!node) {
    return false;
  }
  const stroke = node.attributes?.stroke;
  if (stroke && !isEmptyPaint(stroke)) {
    return true;
  }
  return (node.children || []).some(hasAnyStroke);
};

const RenderSvgNodes = ({ node, colors }: { node: INode; colors?: Record<string, string> }) => {
  if (!node) {
    return null;
  }

  const { name, attributes, children } = node;

  const filteredAttributes = Object.fromEntries(
    Object.entries(attributes).filter(([key]) =>
      ALLOWED_SHAPE_ATTRIBUTES.includes(key as (typeof ALLOWED_SHAPE_ATTRIBUTES)[number])
    )
  );

  const renderChildren = () => {
    return children.map((child, i) => <RenderSvgNodes key={i} node={child} colors={colors} />);
  };

  const colorKeys = Object.keys(colors || {});
  const isSingleColorViaCurrentColor = colors !== undefined && colorKeys.length === 0;
  const isSingleColorViaDefault = colorKeys.length === 1 && Boolean(colors?.[DEFAULT_COLOR]);

  const resolveColor = (originalColor: string | undefined) => {
    if (isEmptyPaint(originalColor)) {
      return originalColor;
    }

    if (isSingleColorViaCurrentColor) {
      return 'currentColor';
    }

    if (isSingleColorViaDefault) {
      const color = colors?.[DEFAULT_COLOR];
      return resolveDocumentColorToCss(color) ?? color;
    }

    const color = (originalColor && colors?.[originalColor]) || originalColor;
    return resolveDocumentColorToCss(color) ?? color;
  };

  // Always set fill so single-color recoloring reaches children that inherit it from a parent group.
  // For stroke, only override when an original stroke exists, so we don't draw outlines that weren't there.
  const paintProps: Record<string, string | undefined> = {
    fill: resolveColor(attributes.fill),
  };
  if (attributes.stroke !== undefined) {
    paintProps.stroke = resolveColor(attributes.stroke);
  }

  return React.createElement(name, { ...filteredAttributes, ...paintProps }, ...renderChildren());
};

export const ShapeViewRenderer = ({
  shapeJson,
  shapeSrc,
  colors,
  getShapeUrl,
  style,
  isLoading,
  hideLoadingOverlay,
  dimensions,
  onShapeLoaded,
  preserveAspectRatio = 'none',
}: {
  shapeSrc: FileSource;
  shapeJson?: INode;
  colors?: Record<string, string>;
  getShapeUrl?: () => string | undefined;
  style?: React.CSSProperties;
  isLoading?: boolean;
  hideLoadingOverlay?: boolean;
  dimensions?: {
    width: number;
    height: number;
  };
  onShapeLoaded?: (dimensions: { width: number; height: number }) => void;
  preserveAspectRatio?: string;
}) => {
  const [localShapeJson, setLocalShapeJson] = useState<INode>();
  const shapeRef = useRef<SVGSVGElement>(null);

  const shape = shapeJson || localShapeJson;

  useEffect(() => {
    if (shapeJson || (!shapeSrc.id && !shapeSrc.url)) {
      return;
    }

    const fetchShape = async () => {
      const parsedShapeJson = await getParsedShape(shapeSrc, getShapeUrl);
      setLocalShapeJson(parsedShapeJson);
    };

    fetchShape();
  }, [shapeSrc.id, shapeSrc.url]);

  useEffect(() => {
    if (!shapeRef.current) {
      return;
    }

    const width = shapeRef.current.clientWidth;
    const height = shapeRef.current.clientHeight;
    onShapeLoaded?.({ width, height });
  }, [shapeRef.current]);

  if (!shape || isLoading) {
    if (hideLoadingOverlay) {
      return null;
    }

    const width = dimensions?.width || shapeRef.current?.clientWidth;
    const height = dimensions?.height || shapeRef.current?.clientHeight;

    return (
      <div
        className={styles.shape_pending_overlay}
        style={{ width: `${width}px`, height: `${height}px` }}
      >
        <span className={styles.shape_pending_overlay_loader}>
          <DoubleLoader />
        </span>
      </div>
    );
  }

  // data-bbox is the geometric bbox; using it on stroked shapes clips half of every stroke,
  // so fall back to the authored viewBox whenever any stroke is present.
  const viewBox = hasAnyStroke(shape)
    ? shape.attributes.viewBox || shape.attributes['data-bbox']
    : shape.attributes['data-bbox'] || shape.attributes.viewBox;

  return (
    <svg
      ref={shapeRef}
      viewBox={viewBox}
      xmlns={shape.attributes.xmlns}
      preserveAspectRatio={preserveAspectRatio}
      aria-hidden="true"
      style={{
        width: 'var(--ricos-internal-resize-width, 100%)',
        maxWidth: '100%',
        ...style,
      }}
    >
      {shape.children.map((child, i) => (
        <RenderSvgNodes key={i} node={child} colors={colors} />
      ))}
    </svg>
  );
};
