import React, { useCallback, useRef, useState } from 'react';

import { SWATCHES } from './../../../../color-picker/common/data-hooks.js';

import { AddColorButton } from '../add-color-button/index.js';
import { SingleColorSwatch } from '../single-color-swatch/index.js';
import classes from './new-color-swatches-scss.js';

interface NewColorSwatchesProps {
  colors: string[];
  deletableColors?: string[];
  selectedColor?: string | undefined;
  onAddClick?: () => void;
  onColorSelected: (color: string | undefined) => void;
  onColorPreviewStart?: (color: string | undefined) => void;
  onColorPreviewEnd?: () => void;
  onColorDeleted?: (color: string) => void;
  dataHook?: string;
  setAddButtonRef?: (ref: HTMLDivElement) => void;
  labelledById?: string;
}

const COLUMN_COUNT = 6;

export const NewColorSwatches: React.FC<NewColorSwatchesProps> = ({
  colors,
  deletableColors,
  selectedColor,
  onAddClick,
  onColorSelected,
  onColorPreviewStart,
  onColorPreviewEnd,
  onColorDeleted,
  dataHook,
  setAddButtonRef,
  labelledById,
}) => {
  const [focusedIndex, setFocusedIndex] = useState<number | null>(null);
  const deletableColorSet = new Set(deletableColors?.map(color => color.toUpperCase()));

  const swatchRefs = useRef<(HTMLDivElement | null)[]>([]);

  const handleKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    if (focusedIndex === null) {
      return;
    }

    let newIndex = focusedIndex;

    switch (event.key) {
      case 'ArrowRight':
        newIndex = (focusedIndex + 1) % colors.length;
        break;
      case 'ArrowLeft':
        newIndex = (focusedIndex - 1 + colors.length) % colors.length;
        break;
      case 'ArrowDown':
        newIndex = (focusedIndex + COLUMN_COUNT) % colors.length;
        break;
      case 'ArrowUp':
        newIndex = (focusedIndex - COLUMN_COUNT + colors.length) % colors.length;
        break;
      default:
        return;
    }

    setFocusedIndex(newIndex);
    event.preventDefault();
    swatchRefs.current[newIndex]?.querySelector('button')?.focus();
  };

  const setColorSwatchRef = useCallback(
    (index: number) => (element: HTMLDivElement | null) => (swatchRefs.current[index] = element),
    []
  );

  return (
    <div
      role="listbox"
      aria-labelledby={labelledById}
      aria-activedescendant={getColorSwatchId(focusedIndex ?? 0)}
      data-hook={dataHook}
      onKeyDown={handleKeyDown}
      tabIndex={0}
      onFocus={() => {
        if (focusedIndex === null) {
          setFocusedIndex(0);
        }
      }}
    >
      <div className={classes.container} data-hook={SWATCHES}>
        {colors.map((color, index) => (
          <SingleColorSwatch
            index={getColorSwatchId(index)}
            key={color}
            fill={color}
            selectedColor={selectedColor}
            onClick={onColorSelected}
            onMouseEnter={onColorPreviewStart}
            onMouseLeave={onColorPreviewEnd}
            onFocus={() => {
              setFocusedIndex(index);
            }}
            onDelete={
              onColorDeleted && deletableColorSet.has(color.toUpperCase())
                ? onColorDeleted
                : undefined
            }
            setRef={setColorSwatchRef(index)}
          />
        ))}
        {!!onAddClick && <AddColorButton onAddClick={onAddClick} setRef={setAddButtonRef} />}
      </div>
    </div>
  );
};

const getColorSwatchId = (index: number) => `color-swatch-${index}`;
