import { type Link as OldLink } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { type Link, Link_Target } from './../../ricos-schema/next-schema/index.js';

type LinkUrlOrAnchor = Pick<Link, 'anchor'> | Pick<Link, 'url' | 'target' | 'rel' | 'customData'>;

export const fromTiptapLinkConverter = (link?: OldLink): LinkUrlOrAnchor | undefined => {
  if (!link) {
    return undefined;
  }

  if (link.anchor) {
    return {
      anchor: link.anchor,
    };
  }

  if (link.url) {
    return {
      url: link.url,
      target: (link.target as Link_Target) ?? Link_Target.BLANK,
      rel: link.rel,
      customData: link.customData,
    };
  }

  return undefined;
};
