import type { ColorInstance } from '@wix/design-system';
import { Box, ColorPicker, FieldSet, IconButton, Input, Slider, Text } from '@wix/design-system';
import { RevertSmall } from '@wix/wix-ui-icons-common/lazy';
import React, { useContext, useMemo, useState } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import type { ThemeColorSwatch } from './../color-manager-utils.js';
import { resolveColorToDisplayHex } from './../resolve-color-to-display-hex.js';
import {
  getThemeColorTokenOpacity,
  isThemeColorToken,
  setThemeColorTokenOpacity,
  stripThemeColorTokenOpacity,
  type ThemeColorToken,
  themeColorTokenToHex,
} from './../theme-color-token.js';
import {
  combineHexWithOpacity,
  getHexColorFromAlpha,
  getOpacityFromHex,
} from './../../wix-rich-content-common/index.js';
import { NewColorSwatches } from './../../ui-components/color-picker/new-color-picker/components/new-color-swatches/index.js';
import {
  Panel,
  useClickOutside,
  usePanelContainerElement,
} from './../../ui-components/index.js';

const FALLBACK_HEX = '#000000';

type ShapeColorPickerModalProps = {
  originalColor: string;
  initialColor: string;
  onColorChange: (originalColor: string, newColor: string) => void;
  onClose: () => void;
  colorsModalElement?: HTMLElement | null;
  themeColors?: ThemeColorSwatch[];
};

const getColorOpacity = (color: string): number =>
  isThemeColorToken(color) ? getThemeColorTokenOpacity(color) : getOpacityFromHex(color);

const setColorOpacity = (color: string, opacity: number): string => {
  if (isThemeColorToken(color)) {
    return setThemeColorTokenOpacity(color, opacity);
  }
  const baseHex = getHexColorFromAlpha(color) ?? color;
  return combineHexWithOpacity(baseHex, opacity) ?? baseHex;
};

export const ShapeColorPickerModal = ({
  originalColor,
  initialColor,
  onColorChange,
  onClose,
  colorsModalElement,
  themeColors = [],
}: ShapeColorPickerModalProps) => {
  const { t, theme } = useContext(RicosContext);
  const palette = theme.colorPalette;
  const containerEl = usePanelContainerElement();

  useClickOutside({
    containerRef: { current: containerEl },
    onClickOutside: (e: MouseEvent | TouchEvent) => {
      const target = e.target as HTMLElement | null;
      if (containerEl?.contains(target as Node) || colorsModalElement?.contains(target as Node)) {
        return;
      }
      onClose();
    },
  });

  // Single source of truth: the persisted color string (token like
  // `$theme-color-3-50` or hex like `#FF000080`). Opacity is read from it.
  const [savedColor, setSavedColor] = useState(initialColor);
  const [opacityInputValue, setOpacityInputValue] = useState(() =>
    String(getColorOpacity(initialColor))
  );
  const opacity = getColorOpacity(savedColor);

  // The WDS color picker shows a hex; resolve a token to its current palette hex.
  const baseHex =
    isThemeColorToken(savedColor) && palette
      ? (getHexColorFromAlpha(themeColorTokenToHex(savedColor, palette) ?? '') ?? FALLBACK_HEX)
      : (getHexColorFromAlpha(savedColor) ?? FALLBACK_HEX);
  const pickerColor = resolveColorToDisplayHex(baseHex, containerEl) ?? baseHex;

  const resolvedThemeColors: ThemeColorSwatch[] = useMemo(
    () =>
      themeColors.flatMap(swatch => {
        const hex = resolveColorToDisplayHex(swatch.hex, containerEl);
        return hex ? [{ ...swatch, hex }] : [];
      }),
    [themeColors, containerEl]
  );

  const themeHexToToken = useMemo(() => {
    const map = new Map<string, ThemeColorToken>();
    for (const swatch of resolvedThemeColors) {
      if (swatch.token) {
        map.set(swatch.hex.toUpperCase(), swatch.token);
      }
    }
    return map;
  }, [resolvedThemeColors]);

  // Highlight a theme swatch only when the saved value is bound to its token —
  // a literal hex that visually matches must NOT highlight a theme swatch.
  const selectedSwatchColor = isThemeColorToken(savedColor)
    ? resolvedThemeColors.find(s => s.token === stripThemeColorTokenOpacity(savedColor))?.hex
    : undefined;

  const commit = (next: string) => {
    setSavedColor(next);
    setOpacityInputValue(String(getColorOpacity(next)));
    onColorChange(originalColor, next);
  };

  const handleColorChange = (color: string | ColorInstance) => {
    const colorValue = typeof color === 'string' ? color : color.hex();
    const hexValue =
      resolveColorToDisplayHex(colorValue, containerEl) ??
      getHexColorFromAlpha(colorValue) ??
      FALLBACK_HEX;
    commit(combineHexWithOpacity(hexValue, opacity) ?? hexValue);
  };

  const handleThemeSwatchSelected = (color: string | undefined) => {
    if (!color) {
      return;
    }
    const token = themeHexToToken.get(color.toUpperCase());
    commit(
      token
        ? setThemeColorTokenOpacity(token, opacity)
        : (combineHexWithOpacity(color, opacity) ?? color)
    );
  };

  const handleOpacityChange = (value: number) => {
    commit(setColorOpacity(savedColor, value));
  };

  const handleReset = () => {
    setSavedColor(originalColor);
    setOpacityInputValue(String(getColorOpacity(originalColor)));
    // Empty string signals a reset to the parent — it restores the original
    // document value itself so the (possibly token-bound) binding stays intact.
    onColorChange(originalColor, '');
  };

  return (
    <Panel width={240}>
      <ColorPicker
        showConverter={false}
        showActionButtons={false}
        value={pickerColor}
        onChange={handleColorChange}
      />
      {resolvedThemeColors.length > 0 && (
        <Box paddingBottom="SP2" paddingLeft="SP3" paddingRight="SP3">
          <NewColorSwatches
            colors={resolvedThemeColors.map(swatch => swatch.hex)}
            selectedColor={selectedSwatchColor}
            onColorSelected={handleThemeSwatchSelected}
          />
        </Box>
      )}
      <Box paddingBottom="SP3" paddingLeft="SP3" paddingRight="SP3">
        <FieldSet legend="Opacity" columns="auto 72px" alignment="center">
          <Box marginRight="12px">
            <Slider
              displayMarks={false}
              gradientColor={pickerColor}
              min={0}
              max={100}
              value={opacity}
              onChange={value => handleOpacityChange(value as number)}
            />
          </Box>
          <Input
            value={opacityInputValue}
            suffix={<Input.Affix>%</Input.Affix>}
            size="small"
            type="number"
            onChange={e => {
              const inputValue = e.target.value;
              setOpacityInputValue(inputValue);
              const numericValue =
                inputValue === '' ? 0 : Math.max(0, Math.min(100, Number(inputValue)));
              commit(setColorOpacity(savedColor, numericValue));
            }}
            onBlur={e => {
              const value = Math.max(0, Math.min(100, Number(e.target.value) || 0));
              handleOpacityChange(value);
            }}
          />
        </FieldSet>
      </Box>

      <Box
        direction="horizontal"
        gap="SP2"
        paddingLeft="SP3"
        paddingRight="SP3"
        paddingBottom="SP3"
        align="space-between"
        verticalAlign="middle"
      >
        <Text size="small">{t('Shape_ColorPicker_ResetDefaultColor')}</Text>
        <IconButton skin="standard" priority="secondary" onClick={handleReset}>
          <RevertSmall />
        </IconButton>
      </Box>
    </Panel>
  );
};
