import React, { Suspense, lazy } from 'react';

import type { LinkModalProps } from './types.js';

const LinkModal = lazy(() =>
  import(/* webpackChunkName: "ricos_link_modal" */ './link-modal.js').then(({ LinkModal }) => ({
    default: LinkModal,
  }))
);

// The link modal UI is heavy (site pages search, sections, attributes panels),
// so it loads in its own chunk instead of being duplicated into every plugin
// chunk whose toolbar has a link button. The fallback approximates the desktop
// panel size (Panel renders at 288px wide) so the floating positioning doesn't
// jump when the real content arrives.
export const LinkModalLazy: React.FC<LinkModalProps> = props => (
  <Suspense fallback={<div style={{ width: 288, height: 200 }} />}>
    <LinkModal {...props} />
  </Suspense>
);
