import React, { useContext } from 'react';

import { SHAPE_TYPE } from './../../ricos-content/consts.js';
import { EditorContext, ModalServiceContext, RicosContext } from './../../ricos-context/index.js';
import { resolveThemeColorsPalette } from './../../_shared/color-manager-utils.js';
import { ShapeColorPickerModal as SharedShapeColorPickerModal } from './../../_shared/plugin-toolbar/shape-color-picker-modal.js';

import { SHAPE_COLOR_PICKER_MODAL_ID, SHAPE_COLORS_MODAL_ID } from '../utils/consts.js';

export const ShapeColorPickerModal = ({
  nodeId,
  originalColor,
  initialColor,
  colorsModalElement,
}: {
  nodeId: string;
  originalColor: string;
  initialColor: string;
  colorsModalElement?: HTMLElement | null;
}) => {
  const { getPublicCommands } = useContext(EditorContext);
  const { theme } = useContext(RicosContext);
  const modalService = useContext(ModalServiceContext);
  const themeColors = resolveThemeColorsPalette(theme);

  const onColorChange = (_originalColor: string, newColor: string) => {
    const publicCommands = getPublicCommands();
    const componentData = publicCommands.getBlockComponentData(nodeId);
    const updatedColorMap = { ...(componentData.styles?.colors || {}) };
    updatedColorMap[_originalColor] = newColor;
    publicCommands.setBlock(nodeId, SHAPE_TYPE, {
      ...componentData,
      styles: {
        ...componentData.styles,
        colors: updatedColorMap,
      },
    });
  };

  const onClose = () => {
    modalService?.closeModal(SHAPE_COLOR_PICKER_MODAL_ID);
    modalService?.closeModal(SHAPE_COLORS_MODAL_ID);
  };

  return (
    <SharedShapeColorPickerModal
      originalColor={originalColor}
      initialColor={initialColor}
      onColorChange={onColorChange}
      onClose={onClose}
      colorsModalElement={colorsModalElement}
      themeColors={themeColors}
    />
  );
};
