import type { INode } from 'svgson';

import type { FileSource } from './../../ricos-schema/next-schema/index.js';
import { getParsedShape } from './../shape-view-renderer/get-parsed-shape.js';

type ShapeColorMap = Record<string, string>;
const DEFAULT_COLOR = '#000000';

export const getShapeStyles = async (src: FileSource, getShapeUrl?: () => string | undefined) => {
  const parsedShapeJson = await getParsedShape(src, getShapeUrl);
  return getDataColorMapRecursive(parsedShapeJson);
};

const getDataColorMapRecursive = (shapeJson: INode): ShapeColorMap => {
  const dataColorMap: ShapeColorMap = {};

  const collect = (value: string | undefined) => {
    if (!value || value === 'none' || value === 'transparent') {
      return;
    }
    dataColorMap[value] = '';
  };

  const traverse = (node: INode): void => {
    collect(node.attributes?.fill);
    collect(node.attributes?.stroke);
    (node.children || []).forEach((child: INode) => traverse(child));
  };

  traverse(shapeJson);

  return !Object.keys(dataColorMap).length ? { [DEFAULT_COLOR]: '' } : dataColorMap;
};
