import type { MediaItem } from '@wix/ambassador-media-public-media-v1-media-item/types';
import React, { useContext } from 'react';

import { SHAPE_TYPE } from './../../ricos-content/index.js';
import { EditorContext, ModalServiceContext } from './../../ricos-context/index.js';
import type { FileSource, ShapeData } from './../../ricos-schema/next-schema/index.js';
import { getShapeStyles } from './../../_shared/shape-select-modal/get-shape-styles.js';
import { ShapeSelectModal as SharedShapeSelectModal } from './../../_shared/shape-select-modal/shape-select-modal.js';
import type { ShapesCategoryId } from './../../_shared/shape-select-modal/types.js';
import type { ShapePluginEditorConfig } from './../utils/types.js';

import { RICOS_DEFAULTS } from '../utils/consts.js';
import { SHAPE_SELECT_MODAL } from '../utils/data-hooks.js';

export const ShapeSelectModal = ({
  nodeId,
  getShapeUrl,
  initialCategoryId,
}: {
  nodeId?: string;
  getShapeUrl?: ShapePluginEditorConfig['getShapeUrl'];
  initialCategoryId?: ShapesCategoryId;
}) => {
  const { getPublicCommands } = useContext(EditorContext);
  const modalService = useContext(ModalServiceContext) || {};

  const closeModal = () => modalService.closeModal(SHAPE_SELECT_MODAL);

  const loadShapeStyles = async (src: FileSource, targetNodeId: string) => {
    const colorMap = await getShapeStyles(src, getShapeUrl);

    getPublicCommands().updateBlock(targetNodeId, SHAPE_TYPE, {
      styles: {
        colors: colorMap,
      },
      isLoading: false,
    });
  };

  const onShapeSelect = async (shape: MediaItem) => {
    const shapeData = shape.assets?.vector?.image;

    if (!shapeData) {
      console.error('Shape data not found');
      return;
    }

    closeModal();

    const src = shapeData.id ? { id: shapeData.id } : { url: shapeData.url };
    const baseShapeData: ShapeData = {
      shape: { src },
      styles: { colors: {} },
    };

    if (nodeId) {
      getPublicCommands().updateBlock(nodeId, SHAPE_TYPE, {
        ...baseShapeData,
        isLoading: true,
        dimensions: undefined,
      });

      await loadShapeStyles(src, nodeId);

      return;
    }

    const newNodeId = getPublicCommands().insertBlockWithBlankLines(SHAPE_TYPE, {
      ...baseShapeData,
      containerData: RICOS_DEFAULTS.containerData,
      isLoading: true,
    });

    await loadShapeStyles(src, newNodeId);
  };

  return (
    <SharedShapeSelectModal
      onShapeSelect={onShapeSelect}
      onClose={closeModal}
      initialCategoryId={initialCategoryId}
    />
  );
};
